"""Generate complete static interior pages. All interactions stay in the browser."""
from pathlib import Path
from html import escape
import hashlib
import re

ROOT = Path(__file__).resolve().parent / 'dist'
about = (ROOT / 'about.html').read_text(encoding='utf-8')
home = (ROOT / 'index.html').read_text(encoding='utf-8')
symbols = re.search(r'<svg class="svg-library".*?</svg>', about, re.S).group()
extra_symbols = '''<symbol id="search" viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5" fill="none" stroke="currentColor" stroke-width="1.6"/><path d="m16 16 5 5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></symbol><symbol id="pin" viewBox="0 0 24 24"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z" fill="none" stroke="currentColor" stroke-width="1.6"/><circle cx="12" cy="10" r="2.5" fill="none" stroke="currentColor" stroke-width="1.6"/></symbol><symbol id="quote" viewBox="0 0 32 32"><path d="M3 17c0-7 3-11 10-13v5c-3 1-5 3-5 6h6v13H3Zm16 0c0-7 3-11 10-13v5c-3 1-5 3-5 6h6v13H19Z" fill="currentColor"/></symbol>'''
symbols = symbols.replace('</defs>', extra_symbols + '</defs>')
legacy_tail = about[about.index('  <div hidden>'):about.index('</body>')]
story = re.search(r'    <section class="ref-section ref-story".*?</section>', home, re.S).group()
comparison = re.search(r'    <section class="ref-section ref-comparison".*?</section>', home, re.S).group()
written = []

def version(name):
    return hashlib.sha256((ROOT / name).read_bytes()).hexdigest()[:10]

def icon(name):
    return f'<svg aria-hidden="true"><use href="#{name}"/></svg>'

def tag(text):
    return f'<span class="ref-label"><svg class="ref-tag-dot" viewBox="0 0 8 8" aria-hidden="true" focusable="false"><circle cx="4" cy="4" r="3" fill="currentColor"/></svg>{escape(text)}</span>'

def button(text, href='contact.html#appointment', white=False):
    return f'<a class="ref-button ref-{"white" if white else "blue"}" href="{href}">{escape(text)} <span class="ref-circle" aria-hidden="true">{icon("arrow")}</span></a>'

def image(name, alt, eager=False):
    return f'<img src="assets/reference/{name}.webp" alt="{escape(alt, quote=True)}" width="1280" height="853" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'

def photo(name, alt, caption=None):
    note = f'<figcaption class="page-photo-note">{icon("tooth")}<span>{caption}</span></figcaption>' if caption else ''
    return f'<figure class="page-frame" {"" if caption else "data-page-image"}>{image(name, alt)}{note}</figure>'

def heading(label, title, copy=''):
    return f'<div class="page-heading"><div>{tag(label)}<h2>{title}</h2></div>{"<p>"+copy+"</p>" if copy else ""}</div>'

def section(content, classes='', id=None):
    return f'<section class="ref-section page-section {classes}"{f" id={id}" if id else ""}>{content}</section>'

def process(items, photo_name='hero-preview'):
    steps = ''.join(f'''<li class="page-process-item"><details class="page-visit-step" name="visit-process" {"open" if i==0 else ""}><summary><span class="page-step-number" aria-hidden="true">0{i+1}</span><span class="page-visit-title" role="heading" aria-level="3">{title}</span><span class="page-step-chevron" aria-hidden="true">{icon('arrow')}</span></summary><div class="page-visit-answer"><p>{copy}</p></div></details></li>''' for i,(title,copy) in enumerate(items))
    return f'''<div class="page-process" data-visit-process><figure class="page-process-photo">{image(photo_name,'A dental team helping a patient feel prepared for care')}<figcaption class="page-process-caption"><span class="page-process-count" aria-hidden="true"><span data-process-number>01</span><small>/ 0{len(items)}</small></span><span><small>Your visit, at your pace</small><span data-process-caption>{items[0][0]}</span></span></figcaption></figure><div class="page-process-steps"><span class="page-process-line" aria-hidden="true"><span></span></span><ol class="page-process-list" aria-label="Steps through your dental visit">{steps}</ol></div></div>'''

def questions(items):
    return '<ul class="page-question-list">' + ''.join(f'<li>{icon("check")}<span>{text}</span></li>' for text in items) + '</ul>'

def faq_items(items, group='page-faq', first=True):
    return ''.join(f'<details class="ref-faq-item" name="{group}" {"open" if i==0 and first else ""}><summary>{q}<span aria-hidden="true"></span></summary><div class="ref-faq-answer"><p>{a}</p></div></details>' for i,(q,a) in enumerate(items))

def faq(label, title, copy, items):
    return section(f'<div class="page-copy">{tag(label)}<h2>{title}</h2><p>{copy}</p>{button("All your questions, answered", "faq.html")}</div><div class="ref-faq-list">{faq_items(items)}</div>', 'page-faq page-muted')

def feature(title, copy, name='consultation'):
    return section(f'<div class="page-feature">{image(name,"A conversation about dental care")}<div class="page-feature-copy"><h2>{title}</h2><p>{copy}</p>{button("Let’s talk about your visit",white=True)}</div></div>')

def appointment():
    return '<section class="ref-section ref-visit-section" id="appointment" aria-labelledby="visit-title" data-site-appointment></section>'

def shell(filename, page, title, lede, hero_image, body, label=None, service=None):
    label = label or title
    head = f'''<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta http-equiv="Content-Security-Policy" content="connect-src 'none'; form-action 'none';"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#0b3039"><meta name="description" content="{escape(lede,quote=True)}"><title>{escape(title)} — Dentora</title><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/jost-latin-variable.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/dm-serif-display-latin.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="site.css?v={version('site.css')}"><link rel="stylesheet" href="pages.css?v={version('pages.css')}">'''
    for script in ('assets/vendor/gsap.min.js','assets/vendor/ScrollTrigger.min.js','assets/vendor/DrawSVGPlugin.min.js','assets/vendor/lenis.min.js','assets/vendor/SplitText.min.js','shared-components.js','app.js','motion.js','pages.js','pages-motion.js'):
        head += f'<script src="{script}?v={version(script)}" defer></script>'
    attributes = f' data-appointment-service="{escape(service,quote=True)}"' if service else ''
    hero = f'''<section class="page-hero-shell" id="home" aria-labelledby="page-title"><div class="page-hero"><img class="page-hero-photo" src="assets/reference/{hero_image}.webp" alt="" aria-hidden="true" width="1600" height="1067" fetchpriority="high" decoding="async"><header class="site-header ref-header" data-site-header></header><div class="page-hero-copy">{tag(label)}<h1 id="page-title">{escape(title)}</h1><p>{lede}</p></div><div class="page-hero-bottom"><div class="hero-marquee-viewport" role="group" aria-label="Dental services ticker"><div class="hero-marquee-track"><div class="hero-marquee-copy"><span>Your Teeth Our Science</span><span>Dental Checkup</span><span>Teeth Cleaning</span><span>Tooth Filling</span><span>Gum Treatment</span><span>Retainers</span></div></div></div></div></div></section>'''
    result = f'''{head}</head><body class="reference-page interior-page" data-page="{page}"{attributes}>{symbols}<a class="skip-link" href="#main">Skip to content</a><main class="reference-site" id="main">{hero}{body}<footer class="ref-footer" id="contact" data-site-footer></footer></main><div class="mobile-nav ref-mobile-nav" id="mobile-nav" role="dialog" aria-modal="true" aria-label="Mobile navigation" hidden data-site-menu></div>{legacy_tail}</body></html>'''
    (ROOT / filename).write_text(result,encoding='utf-8')
    written.append(filename)

SERVICES = [
    dict(slug='dental-checkups',title='Dental checkups',short='A closer look. A clearer picture.',category='Everyday care',photo='journal-exam',form='Dental checkup',intro='Make room for the questions you’ve been meaning to ask. A checkup is a chance to talk about your oral health and understand what happens next.',overview='Your mouth. Your history.<br>Your next step.',copy='Start with a conversation about how your teeth and gums feel, your daily routine and any changes you have noticed. Your dentist can explain the assessment and discuss any findings with you.',copy2='The right time between visits varies from person to person. Ask your dentist to recommend a checkup interval based on your own needs, rather than following a fixed schedule.',ask=['What does today’s examination include?','Do I need any further assessment, and why?','When would you recommend my next checkup?'],steps=[('Tell us your story.','Bring your questions and share any relevant changes in your health, medicines or dental history.'),('Understand the assessment.','Ask your dentist what they are checking and what any findings mean for you.'),('Leave with a clear plan.','Talk through recommendations, costs and the suggested timing for your next visit.')],faqs=[('How often should I arrange a checkup?','Your dentist can recommend an interval suited to your oral health, history and individual needs. Ask for an explanation of the recommended timing.'),('Will I need treatment at the same visit?','An assessment comes first. Discuss any recommended treatment, alternatives, timing and cost before making a decision.'),('Can I come in with one specific concern?','Yes. When contacting a dental clinic, describe the concern and when it began so the team can advise on the appropriate appointment.')]),
    dict(slug='teeth-cleaning',title='Teeth cleaning',short='A fresh start for your daily routine.',category='Everyday care',photo='journal-cleaning',form='Teeth cleaning',intro='A professional conversation about keeping your teeth and gums cared for, with time to review the habits you use at home.',overview='Care in the chair.<br>Confidence at home.',copy='A cleaning appointment is an opportunity to ask about plaque, areas that are difficult to reach and the tools your dental professional recommends. The approach will depend on your assessment.',copy2='Daily brushing and cleaning between your teeth still matter between visits. Tell the team which parts of your routine are difficult so you can work through practical changes together.',ask=['What will the cleaning involve for me?','Which areas need more attention at home?','What should I expect after the appointment?'],steps=[('Review your routine.','Talk about the products you use, sensitive areas and anything that makes daily care difficult.'),('Discuss your cleaning.','Your clinician can explain the proposed approach and answer questions before starting.'),('Make home care manageable.','Ask for a demonstration and recommendations that fit your own teeth and gums.')],faqs=[('Does a cleaning replace brushing?','No. Professional care supports your daily routine. Continue the home-care approach recommended by your dentist or hygienist.'),('What if my teeth are sensitive?','Mention sensitivity before the appointment. The clinician can discuss what might help and whether further assessment is needed.'),('How often do I need a cleaning?','The timing depends on your assessment and oral health needs. Ask your dental professional to explain their recommendation.')]),
    dict(slug='tooth-fillings',title='Tooth fillings',short='Understand your options. Restore with care.',category='Restorative care',photo='hero-preview',form='Tooth filling',intro='A clear explanation of restorative options, from the reason a filling is recommended to what you can expect during your visit.',overview='Small details.<br>A considered decision.',copy='If a filling is recommended, ask your dentist to explain the area being treated and the options available. Your tooth, bite, preferences and the extent of treatment all belong in the conversation.',copy2='Discuss the material, the steps involved and the expected cost before treatment. Existing dental work also needs ongoing care, so ask how to look after it and what changes to report.',ask=['Why is a filling recommended for this tooth?','Which materials or other options are suitable?','How should I care for the restoration afterwards?'],steps=[('Assess the tooth.','Explain your symptoms and let your dentist assess the tooth before deciding on treatment.'),('Choose with understanding.','Talk through suitable materials, alternatives, comfort measures and costs.'),('Review your aftercare.','Ask what to expect, what to do if your bite feels different and when to seek advice.')],faqs=[('Can I choose a tooth-coloured filling?','Ask your dentist which materials are suitable for the tooth and the treatment involved. Suitability is determined after assessment.'),('How long will a filling last?','No restoration lasts forever. Its condition, your bite and your daily care all matter. Your dentist can review existing fillings at checkups.'),('What if I already have a filling that feels different?','Tell a dentist about a new change in comfort, your bite or the filling itself. An examination can help determine the next step.')]),
    dict(slug='gum-care',title='Gum care',short='Attention to the foundation of your smile.',category='Everyday care',photo='consultation',form='Gum care',intro='Talk about changes in your gums, ask what they mean and work towards a care routine you understand.',overview='Listen to the details.<br>Look after the foundations.',copy='If you have noticed a change in how your gums look or feel, make it part of the conversation. Explain when it started, whether it has changed and anything you have already tried.',copy2='A dental professional can assess your gums and discuss appropriate care. Ask for guidance on brushing and cleaning between your teeth, including a demonstration if that would help.',ask=['What does my gum assessment show?','Which home-care tools are right for me?','What follow-up would you recommend?'],steps=[('Share what has changed.','Bring your questions about the appearance or comfort of your gums and your current routine.'),('Understand the findings.','Ask the clinician to explain the assessment and any suggested care or further investigation.'),('Build a realistic routine.','Discuss daily care, follow-up visits and how to recognise changes that need attention.')],faqs=[('Should I mention bleeding when brushing?','Yes. Tell a dental professional about bleeding or other changes in your gums, including how often it happens and when it began.'),('Do I need special products?','Ask the clinician which tools and products are appropriate after your assessment. Bring the products you currently use if you have questions.'),('Can I discuss gum care at a checkup?','Yes. Your checkup is an opportunity to raise concerns about your gums and ask about suitable next steps.')]),
    dict(slug='retainers',title='Retainers',short='Keep your next chapter in mind.',category='Smile care',photo='journal-visit',form='Retainers',intro='Practical support for understanding your retainer, your wear instructions and the questions that come after orthodontic treatment.',overview='The little routine<br>after the big change.',copy='Retainers help maintain the position of teeth after orthodontic treatment. The type of retainer and the wear schedule should follow the instructions of your treating dental or orthodontic team.',copy2='Bring your retainer to review visits if the clinic asks you to. If it no longer fits, feels damaged or has gone missing, contact the team for advice rather than trying to change it yourself.',ask=['What wear schedule should I follow?','How should I clean and store my retainer?','Who should I contact if it feels different?'],steps=[('Review the fit.','Describe how your retainer feels and share any changes since your last appointment.'),('Check your instructions.','Ask for clear guidance on wear, cleaning, storage and any planned review visits.'),('Know your next step.','Find out what to do if it is lost, broken or uncomfortable so you have a plan.')],faqs=[('How often should I wear my retainer?','Follow the schedule from the clinician who manages your orthodontic care. Ask them if you are unsure or have not worn it for some time.'),('What if my retainer no longer fits?','Contact your dental or orthodontic team for advice. Do not force it into place or attempt to reshape it yourself.'),('Can I ask about a replacement?','Yes. The team can explain whether an assessment is needed and discuss appropriate replacement options and costs.')]),
    dict(slug='cosmetic-dentistry',title='Cosmetic dentistry',short='Your smile, with your goals in view.',category='Smile care',photo='benefit-patient',form='Cosmetic consultation',intro='Explore what you would like to change, what is suitable for your oral health and what a realistic plan could involve.',overview='A conversation first.<br>A choice that feels yours.',copy='Start by describing what you would like to change about your smile. A consultation gives you room to discuss options, existing dental work, oral health and the results that may be realistic.',copy2='Whitening and other cosmetic treatments are not suitable for everyone. Ask your dentist to explain suitability, alternatives, sensitivity, ongoing care and costs before deciding.',ask=['Which options are suitable for my teeth?','How could existing dental work affect the result?','What are the limitations and ongoing care needs?'],steps=[('Tell us your goals.','Bring the questions and details that would help explain what matters most to you.'),('Explore suitable options.','Discuss your oral health, the available approaches and what each one can and cannot do.'),('Take time to decide.','Review the proposed plan, costs, aftercare and alternatives before choosing your next step.')],faqs=[('Can every tooth be whitened?','Whitening does not work in the same way on all discolouration, and restorations such as crowns and fillings do not whiten like natural teeth. Ask your dentist what this means for your smile.'),('Can I discuss options without deciding immediately?','Yes. Ask for explanations of the options, limitations, costs and care involved so you can make an informed decision in your own time.'),('Is the comparison image a real treatment result?','No. The website’s smile comparison is an illustration for the design. It does not predict an individual result or represent a documented patient case.')]),
]

def service_card(service, number=None):
    return f'''<a class="page-service-card" href="service-{service['slug']}.html">{image(service['photo'],'Dental care and patient consultation')}{tag(service['category'])}<div><h3>{service['title']}</h3><div class="page-service-detail"><span><p>{service['short']}</p><span class="page-card-arrow">Explore this service {icon('arrow')}</span></span></div></div></a>'''

service_intro = section(f'''<div class="page-copy">{tag('Care for every chapter')}<h2>Find the care<br>that fits your smile.</h2><p>Every visit starts with you: your questions, your everyday routine and what you’d like to feel more confident about.</p><p>Explore the services below, then talk through the right next step with a dental professional. You don’t need to arrive with all the answers.</p>{button('Meet the Dentora approach','about.html')}</div>{photo('consultation','A dentist explaining care to a patient','A clear conversation.<br>A plan you understand.')}''','page-split')
service_grid = section(heading('Our services','A little everyday care.<br>A lasting difference.','From routine appointments to a conversation about your smile, start with the things that matter to you.') + '<div class="page-service-grid">' + ''.join(service_card(s) for s in SERVICES) + '</div>','page-muted','all-services')
service_process = section(heading('Your visit, made clearer','Care, at your pace.') + process([('Start with a question.','Tell the team what brings you in. It’s okay if you don’t know which service to choose.'),('Make sense of the options.','Ask about your assessment, the proposed plan, alternatives and costs before deciding.'),('Leave knowing what’s next.','Discuss aftercare and when to return. Ask the team to explain anything that feels unclear.')]))
shell('services.html','services','Good care starts with understanding.','Dental services built around clear conversations, thoughtful planning and the needs of your smile.','hero-preview',service_intro+service_grid+service_process+feature('Not sure where to begin?','You can start with a question. Explore the appointment section and tell the team what you would like to discuss.')+appointment(),label='Our dental services')

for index,service in enumerate(SERVICES):
    crumbs = f'<nav class="page-breadcrumb" aria-label="Breadcrumb"><a href="index.html">Home</a><span aria-hidden="true">/</span><a href="services.html">Services</a><span aria-hidden="true">/</span><span aria-current="page">{service["title"]}</span></nav>'
    overview = section(f'''<div class="page-copy">{crumbs}{tag(service['category'])}<h2>{service['overview']}</h2><p>{service['copy']}</p><p>{service['copy2']}</p>{button('Plan a visit','#appointment')}</div>{photo(service['photo'],'A dental professional discussing or providing care','Your questions are part of the appointment.')}''','page-split')
    expect = section(heading('What to expect','A clear path through your visit.')+process(service['steps'],service['photo']),'page-muted', 'your-visit')
    ask = section(photo('consultation','A dentist discussing options using a dental model') + f'<div class="page-copy">{tag("Make room for your questions")}<h2>Ask the things<br>that matter to you.</h2><p>You deserve to understand the recommendation before choosing what happens next. These questions can help start the conversation.</p>{questions(service["ask"])}</div>','page-split')
    related = [SERVICES[(index+1)%6],SERVICES[(index+2)%6],SERVICES[(index+3)%6]]
    body = overview + expect + ask + faq('A few helpful answers','Before your visit.','A little preparation can make the next conversation feel easier.',service['faqs']) + section(heading('More ways to care','Explore another chapter.')+'<div class="page-service-grid">'+''.join(service_card(s) for s in related)+'</div>','page-related') + appointment()
    shell(f'service-{service["slug"]}.html','service',service['title'],service['intro'],service['photo'],body,label=service['category'],service=service['form'])

ARTICLES = [
    dict(slug='cleaning-and-brushing',title='Professional cleaning and daily brushing: how they fit together',category='Dental health',photo='journal-cleaning',minutes=4,summary='Make sense of the care you do at home and the questions to bring to a professional cleaning.',sections=[('Two parts of looking after your smile','Daily care and appointments belong in the same conversation. At home, the American Dental Association recommends brushing twice a day for two minutes with fluoride toothpaste, along with cleaning between your teeth daily. Your dental professional can help you adapt the routine to your needs.','A professional cleaning is an opportunity to discuss areas that are hard to reach and ask about the condition of your teeth and gums. The assessment helps determine what care is appropriate; an appointment does not replace your daily routine.'),('Bring your routine into the conversation','Tell the clinician which brush, toothpaste and interdental tools you use. You can also mention times when you find the routine difficult, such as reaching around dental work or fitting care into a busy day.','If a technique is unclear, ask for a demonstration. A practical explanation can make it easier to understand what you are aiming for rather than simply adding more products.'),('Leave with a plan you can use','Before you leave, ask which areas need attention, what the recommended home-care approach looks like and when your next review should be. Make sure you know who to contact if you have a concern after the appointment.','Your routine should be understandable and manageable. Write down the advice you would like to remember and bring any follow-up questions to your next visit.')],takeaway='Ask for advice you can put into practice at home, including a demonstration of any unfamiliar technique.',source=('ADA: brushing your teeth','https://www.mouthhealthy.org/all-topics-a-z/brushing-your-teeth/')),
    dict(slug='when-to-visit',title='Noticed a change? Preparing to talk to your dentist',category='Dental health',photo='journal-exam',minutes=3,summary='What to note before a dental conversation, from when a concern began to the questions you want answered.',sections=[('Describe what feels different','When something about your teeth, gums or mouth feels different, a clear description can help you explain the concern. Note when you first noticed it, whether it comes and goes and anything that seems to affect it.','Contact a dental professional to discuss the appropriate next step. An online article cannot assess the cause or replace an examination, and you do not need to work out a diagnosis before asking for help.'),('Bring the useful details','Think about recent dental work, any relevant changes in your health and the medicines you take. Ask the clinic what information they would like you to bring, including records from previous care if needed.','It can help to write your questions down before the visit. Tell the team if something makes dental appointments difficult or if you would like extra explanations along the way.'),('Ask what happens next','After the assessment, ask the dentist to explain their findings in everyday language. If treatment or further investigation is recommended, discuss the reason, the alternatives and the expected cost.','Before leaving, check that you understand the next step and whom to contact if the situation changes. A clear plan includes space for your questions.')],takeaway='A short note about when a change started and how it feels can make the conversation more useful.',source=('NHS: dental check-ups','https://www.nhs.uk/Live-well/healthy-teeth-and-gums/dental-check-ups/')),
    dict(slug='dental-checkup',title='Your dental checkup: questions worth bringing with you',category='Dental health',photo='consultation',minutes=4,summary='A checkup is a conversation as well as an assessment. Here is how to make room for both.',sections=[('Start with what matters to you','A checkup is a good time to raise questions about your oral health, dental history and the things you notice in everyday life. Tell your dentist about changes in your general health and medicines as well as concerns about your mouth.','If your visit has a particular goal, say so at the beginning. You might want help understanding a previous recommendation, advice on your routine or a clearer idea of the next step.'),('Understand the recommendation','Ask what the assessment involves and what the findings mean. If an X-ray, treatment or another appointment is suggested, ask why it is recommended and how it will inform your care.','You can also ask about alternatives, costs and the time involved. Take a moment to repeat back the plan if that helps you check your understanding.'),('Agree when to return','The NHS explains that the time between dental checkups depends on individual needs. A single interval is not right for everyone. Ask your dentist what timing they recommend and why.','Before leaving, ask what changes should prompt you to contact the clinic sooner. Keep a note of your questions so you can return to them at the next appointment.')],takeaway='Ask “why this timing for me?” when discussing your next checkup.',source=('NHS: dental check-ups','https://www.nhs.uk/Live-well/healthy-teeth-and-gums/dental-check-ups/')),
    dict(slug='first-visit',title='A more comfortable first dental visit starts before you arrive',category='First visit',photo='about-patient',minutes=3,summary='A little preparation, a few questions and room to tell the team what would help you feel at ease.',sections=[('Know the practical details','Before the appointment, ask the clinic where to arrive, how long to allow and what information to bring. Confirm the purpose of the visit so you know whether it is an initial conversation, an examination or planned treatment.','Prepare a list of medicines and relevant health information if the team requests it. Previous records may also be useful; the clinic can explain whether they are needed.'),('Tell the team what would help','You do not need to hide a difficult previous experience or uncertainty about treatment. Say if you would prefer each step explained, need a moment to ask questions or would like to discuss comfort before anything begins.','A first conversation can focus on what matters to you. The team can then explain the assessment and discuss a plan with those details in mind.'),('Make space for the decision','If treatment is proposed, ask what it involves, whether there are alternatives and what the cost and follow-up may be. It is useful to understand the plan in language that feels clear to you.','Before you leave, check the next step and how to raise any questions you think of afterwards. You can bring notes to make the conversation easier to remember.')],takeaway='Write down the questions you most want answered. Bring the list into the room with you.',source=None),
    dict(slug='whitening-questions',title='Thinking about teeth whitening? Start with these questions',category='Smile care',photo='benefit-patient',minutes=4,summary='Consider suitability, existing dental work and realistic expectations before choosing a cosmetic treatment.',sections=[('Begin with suitability','A whitening conversation should start with your oral health and the reason you would like a change. Ask a dentist whether whitening is appropriate for your teeth and gums before deciding on a product or treatment.','Not every type of discolouration responds in the same way. Your dentist can explain the options and limitations after assessing your smile.'),('Ask about existing dental work','Crowns, veneers and fillings do not whiten in the same way as natural teeth. Mention any existing dental work and ask how it might affect the overall appearance.','Bring your expectations into the discussion. Ask what changes may be realistic and whether other steps need to be considered before a whitening plan.'),('Understand care and expectations','Ask about sensitivity, the proposed process, cost and any follow-up. Find out what care is recommended during and after treatment and who to contact if you have concerns.','Comparison pictures on this website are illustrative design assets. They are not patient records, a promise of a result or a substitute for a personal assessment.')],takeaway='A useful cosmetic consultation explains both the possibilities and the limits.',source=('ADA: teeth whitening','https://www.mouthhealthy.org/all-topics-a-z/teeth-whitening')),
    dict(slug='family-care',title='Making dental care part of your family’s everyday routine',category='Family care',photo='journal-visit',minutes=3,summary='Practical conversations that help each family member understand their own care and next appointment.',sections=[('Start with the routine you have','A family conversation about dental care can begin with what already works and what feels difficult. Think about timing, the tools you use and whether each person needs different support.','Bring those details to the dental team. Advice can be more useful when it takes account of real routines rather than assuming the same approach works for everyone.'),('Make the next visit easier to understand','Before an appointment, ask what the visit involves and what information to bring for each person. Keep health information and questions separate so each person’s needs can be discussed clearly.','If a family member feels unsure about dental visits, tell the clinic when arranging the appointment. Ask how the team can explain the process and what preparation might help.'),('Keep the plan personal','Ask the dentist to explain the recommended care and review timing for each family member. A clear plan should say what happens next and how to ask questions between appointments.','Write down the details you want to remember, including any demonstrations or product advice. Bring back anything that did not feel clear so it can be explained again.')],takeaway='One family can have several different care plans. Make time for each person’s questions.',source=None),
]

def article_card(article):
    category = article['category']
    return f'''<a class="page-journal-card" href="article-{article['slug']}.html" data-category="{category.lower().replace(' ','-')}"><span class="page-journal-photo">{image(article['photo'],'Dental care in a clinic')}{tag('#'+category.title().replace(' ',''))}</span><span class="page-journal-card-copy"><span class="page-journal-meta"><span>Dentora Journal</span><span>{article['minutes']} min read</span></span><h3>{article['title']}</h3><p>{article['summary']}</p><span class="page-card-arrow">Read the article {icon('arrow')}</span></span></a>'''

toolbar = f'''<div class="page-toolbar"><div class="page-filters" role="group" aria-label="Filter journal articles">{''.join(f'<button class="page-filter" type="button" data-filter="{key}" aria-pressed="{str(key=="all").lower()}">{label}</button>' for key,label in [('all','All articles'),('dental-health','Dental health'),('first-visit','First visit'),('smile-care','Smile care'),('family-care','Family care')])}</div><label class="page-search">{icon('search')}<input type="search" placeholder="Search the journal" aria-label="Search the journal"></label></div>'''
journal_body = section(heading('From the journal','A little knowledge.<br>A clearer conversation.','Thoughtful reading to help you prepare for a visit, ask better questions and understand the care you discuss.') + toolbar + '<p class="page-result-count" data-result-count aria-live="polite"></p><div class="page-journal-grid">'+''.join(article_card(a) for a in ARTICLES)+'</div><p class="page-empty" data-empty hidden>No articles match. Try another topic or search.</p>','', 'journal-library')
journal_body = journal_body.replace('id=journal-library','id=journal-library data-filter-region="journal"')
shell('journal.html','journal','Room for your questions.','Simple, thoughtful reading about dental visits, everyday care and the conversations that help you feel prepared.','journal-visit',journal_body+feature('Reading is a start.<br>A conversation comes next.','Bring the questions you have gathered to your appointment. Your own dental assessment is the place to discuss what is right for you.','consultation'),label='The Dentora journal')

for index,article in enumerate(ARTICLES):
    contents = ''.join(f'<a href="#reading-{i+1}">{title}</a>' for i,(title,*_) in enumerate(article['sections']))
    reading = f'<div class="page-article-meta"><span>By Dentora Journal</span><span>{article["minutes"]} min read</span><span>Patient information</span></div>'
    for i,(title,p1,p2) in enumerate(article['sections']):
        reading += f'<section id="reading-{i+1}"><h2>{title}</h2><p>{p1}</p><p>{p2}</p></section>'
        if i == 0:
            reading += photo(article['photo'],'A dental appointment and conversation')
        if i == 1:
            reading += f'<aside class="page-article-callout"><p>{article["takeaway"]}</p></aside>'
    if article['source']:
        source_title,url = article['source']
        reading += f'<div class="page-sources"><p>Further reading: <a href="{url}" target="_blank" rel="noopener noreferrer">{source_title}</a>.</p></div>'
    reading += '<p class="page-note">General information for preparing a conversation with your dental team. Your own assessment guides your care.</p>'
    related = [ARTICLES[(index+1)%6],ARTICLES[(index+2)%6],ARTICLES[(index+3)%6]]
    body = section(f'<aside class="page-article-aside"><p>In this article</p><nav aria-label="Article contents">{contents}</nav>{button("Plan your visit")}</aside><article class="page-article-body">{reading}</article>','page-article-layout') + section(heading('Keep reading','More to explore.')+'<div class="page-journal-grid">'+''.join(article_card(a) for a in related)+'</div>','page-muted')
    shell(f'article-{article["slug"]}.html','article',article['title'],article['summary'],article['photo'],body,label='#'+article['category'].title().replace(' ',''))

review_grid = section(heading('The feeling we aim for','Heard. Informed.<br>A little more at ease.','Illustrative stories showing the kind of conversations we value. These are sample testimonials, not verified patient reviews.')+'<div class="page-review-grid">'+''.join(f'<article class="page-review">{icon("quote")}<blockquote>{quote}</blockquote><div class="page-review-person">{image(photo_name,"")}<span>{name}<small>Sample testimonial</small></span></div></article>' for name,photo_name,quote in [('Alex R.','story-man','“There was room for all our questions, and the next steps felt easier to understand.”'),('Jamie L.','about-woman','“I could talk about what mattered to me before deciding on a plan.”'),('Sam P.','story-woman','“A calm conversation made the idea of coming back feel more manageable.”')])+'</div>','page-muted')
shell('reviews.html','reviews','Every smile has a story.','Time to listen, space for questions and the care we want every person to feel.','benefit-patient',story+review_grid+comparison+feature('Your story matters, too.','Tell the team what would help you feel comfortable. Your questions are a good place to start.','about-patient')+appointment(),label='Patient perspectives')

contact_cards = section('<div class="page-contact-strip">'+f'''<div class="page-contact-detail">{icon('phone')}<h2>Let’s talk.</h2><p><a href="tel:+12025550147">+1 (202) 555-0147</a><br><a href="mailto:dentora@example.com">dentora@example.com</a></p></div><div class="page-contact-detail">{icon('pin')}<h2>Find our space.</h2><address>24 Smile Avenue, Suite 101<br>Example City, NY 10001</address></div><div class="page-contact-detail">{icon('calendar')}<h2>Plan your time.</h2><p>Monday–Friday · 9 am–6 pm<br>Saturday · 9 am–1 pm<br>Sunday · Closed</p></div>'''+'</div>')
contact_welcome = section(photo('treatment-room','A bright dental treatment room','A calmer space.<br>A conversation at your pace.')+f'<div class="page-copy">{tag("Before you arrive")}<h2>Make yourself<br>a little more at ease.</h2><p>Ask about arrival details, the purpose of your visit and how much time to allow. Tell the team about any access needs or previous dental experiences you would like to discuss.</p>{questions(["Bring the questions you want to ask.","Check which records and health information to bring.","Ask about the proposed care and costs before deciding."])}<p class="page-note">The address, contact details and opening hours shown here are fictional details for this frontend demonstration.</p></div>','page-split page-muted')
shell('contact.html','contact','A good conversation starts here.','A question, a first visit or a fresh start. Make room for the dental care you would like to talk about.','consultation',contact_cards+contact_welcome+appointment()+faq('Before you say hello','A few practical answers.','Feel a little more prepared before your next conversation.',[('Can I book through this website?','This is a frontend demonstration. The appointment and newsletter forms do not send information or create a booking.'),('What information should I prepare?','Write down your questions and ask the clinic which health information and records to bring for the planned visit.'),('Are these real clinic contact details?','No. The contact details, address and opening hours are fictional details used to demonstrate the design.')]),label='Contact Dentora')

FAQ_GROUPS = [
    ('Getting started',[('Can I book through the website?','This website is a frontend demonstration. Its forms do not submit, send, save or create an appointment. The contact details are fictional design details.'),('What should I bring to my first visit?','Ask the clinic what to bring when confirming an appointment. A list of your questions, medicines and relevant dental or health history can help the conversation.'),('What if I am nervous about dental appointments?','Tell the team about your concerns before the visit. Ask how each step will be explained and discuss what would help you feel more comfortable.')]),
    ('Dental services',[('Which services can I learn about?','Explore dental checkups, teeth cleaning, tooth fillings, gum care, retainers and cosmetic consultations. Suitability and any treatment plan require an individual dental assessment.'),('How often should I have a checkup?','The interval depends on your oral health and individual needs. Ask your dentist to explain the recommended timing for you.'),('Can I ask about costs before choosing treatment?','Yes. Ask for an explanation of the proposed treatment, alternatives, costs and follow-up before deciding how to proceed.'),('How do I know if whitening is right for me?','A dentist can assess your teeth and gums and explain the options and limitations. Existing restorations and the type of discolouration can affect what is suitable.')]),
    ('Planning your care',[('Can I discuss more than one concern?','Bring a list of the concerns you would like to discuss. Tell the clinic when arranging your visit so they can advise on the appropriate appointment.'),('What should I do about a damaged retainer?','Contact your treating dental or orthodontic team for advice. Do not try to reshape it or force it into place.'),('Are the reviews and comparison real patient results?','No. Testimonials are labelled sample stories, and the comparison uses illustrative imagery. Neither is a verified patient account or a prediction of an individual outcome.')]),
]
faq_content = ''.join(f'<div class="page-faq-group" data-category="{title.lower().replace(" ","-")}"><h3>{title}</h3><div class="ref-faq-list">{faq_items(items,"all-faqs",first=i==0)}</div></div>' for i,(title,items) in enumerate(FAQ_GROUPS))
faq_full = section(f'<div class="page-copy">{tag("A few helpful answers")}<h2>Clarity before<br>your next visit.</h2><p>Start with the practical details. For advice about your own teeth and gums, speak with a dental professional.</p>{button("Explore dental services","services.html")}</div><div><div class="page-toolbar"><label class="page-search">{icon("search")}<input type="search" placeholder="Find an answer" aria-label="Search frequently asked questions"></label></div>{faq_content}<p class="page-empty" data-empty hidden>No topics match. Try another search.</p></div>','page-faq page-muted')
faq_full = faq_full.replace('class="ref-section page-section page-faq page-muted"','class="ref-section page-section page-faq page-muted" data-filter-region="faq"')
shell('faq.html','faq','Your questions belong here.','Helpful answers about preparing for a dental visit, exploring services and understanding how this website works.','consultation',faq_full+appointment(),label='Frequently asked questions')

privacy = '''<p>This Dentora website is a frontend design demonstration. The contact information is fictional. No clinic booking, email delivery, payment service or patient database is connected.</p><h2>Information entered in forms</h2><p>The appointment and newsletter controls do not submit your details. This site does not send or store the name, email address, phone number, date or message you type. Input stays in the current page until you clear it, reload or leave; your browser may independently offer its own autofill features.</p><h2>Local assets and browser features</h2><p>Fonts, images and animation libraries are served from the same site. The website does not include advertising pixels or analytics scripts and does not use cookies or browser storage to record form entries. Your browser requests the files required to display the pages.</p><h2>Hosting and external links</h2><p>A hosting provider may process ordinary request information when serving website files according to its own practices. Educational articles include links to independent information sources. Opening an external link takes you to a site with its own privacy practices.</p><h2>Appointments and personal information</h2><p>This demonstration is not a channel for sending medical information or requesting care. Any future live clinic service would need its own verified contact details, working booking arrangements and privacy information.</p>'''
terms = '''<p>Dentora is a static website demonstration of a dental practice design. Its purpose is to show page layouts, navigation and frontend interactions.</p><h2>Demonstration content</h2><p>Clinic contact details, the address and opening hours are fictional. People shown in stock photographs do not imply endorsement. Testimonials are labelled sample stories. The comparison image is illustrative and does not document a patient’s treatment or promise a result.</p><h2>No online bookings</h2><p>Appointment and newsletter forms do not send or save details, book a visit or subscribe anyone. No payment, messaging, email, automation or patient-management service is connected to these pages.</p><h2>Dental information</h2><p>Service descriptions and journal articles offer general information to prepare questions for a dental conversation. They do not diagnose a condition or determine which treatment is suitable for a person. Individual care decisions require assessment by an appropriate dental professional.</p><h2>Links and accessibility</h2><p>External educational links lead to independent websites. This site supports keyboard navigation, reduced-motion preferences and layouts that adapt to screen size. Interactive controls may behave differently if JavaScript is disabled; the main written content remains readable, while shared navigation and enhanced controls require JavaScript.</p>'''
shell('privacy.html','privacy','Your details stay with you.','A straightforward explanation of information and forms in this frontend demonstration.','treatment-room',section(f'<article class="page-legal">{privacy}{button("Back to Home","index.html")}</article>'),label='Privacy information')
shell('terms.html','terms','A few clear details.','How to understand the content and interactive features in this Dentora design demonstration.','consultation',section(f'<article class="page-legal">{terms}{button("Back to Home","index.html")}</article>'),label='Website terms')
shell('404.html','404','A little off the usual path.','The page you are looking for may have moved. There is still plenty to explore.','treatment-room',section(f'<div class="page-copy">{tag("404 · Page not found")}<h2>Let’s find your way back.</h2><p>Explore our dental services or return to the homepage to start again.</p>{button("Return to Home","index.html")} {button("Explore services","services.html")}</div>'),label='Page not found')

# Local Home cards lead to complete editorial pages; the published showcase can
# still opt into the existing data-link-mode="placeholder" behavior.
for index,article in enumerate(ARTICLES):
    pattern = rf'<button class="ref-article" type="button" data-article="{index}">(.*?)</button>'
    home = re.sub(pattern,lambda m: f'<a class="ref-article" href="article-{article["slug"]}.html">{m.group(1)}</a>',home,flags=re.S)
    link_pattern = rf'(<a class="ref-article" href="article-{article["slug"]}.html">)(.*?)(</a>)'
    def update_card(match):
        content = re.sub(r'<strong>.*?</strong>',f'<strong>{article["title"]}</strong>',match.group(2))
        content = re.sub(r'<small>.*?</small>',f'<small>{article["minutes"]} Min read</small>',content)
        content = content.replace('Sarah Johnson','Dentora Journal').replace('Nataly Birch','Dentora Journal').replace('Cody Fisher','Dentora Journal')
        return match.group(1)+content+match.group(3)
    home = re.sub(link_pattern,update_card,home,flags=re.S)
home = re.sub(r'<button class="ref-button ref-blue" type="button" data-info="journal">(.*?)</button>',r'<a class="ref-button ref-blue" href="journal.html">\1</a>',home,flags=re.S)
home = home.replace('Explore all our FAQs','Explore all our FAQs')
(ROOT / 'index.html').write_text(home,encoding='utf-8')
about = about.replace('href="index.html#faq"','href="faq.html"')
(ROOT / 'about.html').write_text(about,encoding='utf-8')

# Cache versions are content-derived on every authored page.
for page in ROOT.glob('*.html'):
    html = page.read_text(encoding='utf-8')
    for name in ('shared-components.js','app.js','motion.js','site.css','about.css','about-motion.js'):
        html = re.sub(re.escape(name)+r'(?:\?v=[\w-]+)?',name+'?v='+version(name),html)
    page.write_text(html,encoding='utf-8')
print(f'Built {len(written)} interior pages; {len(list(ROOT.glob("*.html")))} HTML pages in total.')
